/**
 * POST /api/notify-me
 *
 * Saves a back-in-stock notification request.
 * Forwards to FastAPI POST /api/v1/notify ΓÇö no auth required (email-based).
 */

import { NextResponse } from "next/server";
import { routeFetch } from "@/lib/apiClient";

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const { productId, productName, productSlug, email, clerkUserId } = body;

    if (!productId || !productName || !productSlug || !email) {
      return NextResponse.json(
        { error: "Missing required fields." },
        { status: 400 }
      );
    }

    // Forward directly to FastAPI ΓÇö no auth token needed for this endpoint
    const result = await fetch(
      `${process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000"}/api/v1/notify`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          product_id: productId,
          product_name: productName,
          product_slug: productSlug,
          email,
          clerk_user_id: clerkUserId ?? null,
        }),
      }
    );

    if (!result.ok) {
      const text = await result.text().catch(() => "");
      throw new Error(`FastAPI ${result.status}: ${text}`);
    }

    const data = await result.json();

    return NextResponse.json({
      success: true,
      message: data.message ?? "Notification request saved.",
    });
  } catch (error) {
    console.error("Notify Me API Error:", error);

    return NextResponse.json(
      {
        error:
          error instanceof Error
            ? error.message
            : "Failed to save notification request.",
      },
      { status: 500 }
    );
  }
}

import { notFound } from "next/navigation";
import { serverFetch } from "@/lib/apiClient";
import CategoryPageClient from "@/features/products/components/CategoryPageClient";
import type { Category } from "@/types/api";

export default async function CategoryPage({
  params,
}: {
  params: Promise<{ category: string }>;
}) {
  const { category } = await params;

  // GET /api/v1/categories/{slug} ΓÇö returns category + all its products
  const categoryData = await serverFetch<Category>(`/categories/${category}`);

  if (!categoryData) {
    notFound();
  }

  return <CategoryPageClient categoryData={{ 
    ...categoryData, 
    _id: categoryData.id,
    description: categoryData.description || "",
    featureTitle: categoryData.featureTitle || "",
    featureImage: categoryData.featureImage ? { asset: { url: categoryData.featureImage } } : undefined,
    featureVideo: categoryData.featureVideo ? { asset: { url: categoryData.featureVideo } } : undefined,
    products: categoryData.products?.map((p: any) => ({
      ...p,
      _id: p.id,
      mainImage: p.mainImage ? { asset: { url: p.mainImage } } : undefined,
    })) || [],
  }} />;
}

import { serverFetch } from "@/lib/apiClient";
import CollectionPageClient from "@/features/products/components/CollectionPageClient";
import type { Category } from "@/types/api";

export default async function CollectionPage() {
  // Fetch all categories with their featured products from FastAPI
  const categories = await serverFetch<Category[]>("/categories");

  const mappedCategories = (categories ?? []).map((cat) => ({
    ...cat,
    _id: cat.id,
    description: cat.description || "",
    featureTitle: cat.featureTitle || "",
    featureImage: cat.featureImage ? { asset: { url: cat.featureImage } } : undefined,
    featureVideo: cat.featureVideo ? { asset: { url: cat.featureVideo } } : undefined,
    products: cat.products?.map((p: any) => ({
      ...p,
      _id: p.id,
      mainImage: p.mainImage ? { asset: { url: p.mainImage } } : undefined,
    })) || [],
  }));

  return <CollectionPageClient categories={mappedCategories} />;
}

"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@clerk/nextjs";
import { 
  getContentHeader, updateContentHeader, 
  getContentPhilosophy, updateContentPhilosophy, 
  getContentHomepage, updateContentHomepage 
} from "@/features/dashboard/api";

export default function ContentEditorPage() {
  const { getToken } = useAuth();

  // Header State
  const [header, setHeader] = useState({ logo_text: "", nav_links: [] as any[] });

  // Homepage State
  const [homepage, setHomepage] = useState({ hero_title: "", hero_subtitle: "", hero_cta: "" });

  // Philosophy State
  const [philosophy, setPhilosophy] = useState({ title: "", description: "", image_url: "" });

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    async function load() {
      const token = await getToken();
      if (!token) return;

      try {
        const [h, hp, p] = await Promise.all([
          getContentHeader(token),
          getContentHomepage(token),
          getContentPhilosophy(token)
        ]);
        if (h) setHeader(h as any);
        if (hp) setHomepage(hp as any);
        if (p) setPhilosophy(p as any);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    }
    load();
  }, [getToken]);

  async function handleSaveHeader(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);
    const token = await getToken();
    if (token) await updateContentHeader(token, header);
    setSaving(false);
    alert("Header saved!");
  }

  async function handleSaveHomepage(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);
    const token = await getToken();
    if (token) await updateContentHomepage(token, homepage);
    setSaving(false);
    alert("Homepage saved!");
  }

  async function handleSavePhilosophy(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);
    const token = await getToken();
    if (token) await updateContentPhilosophy(token, philosophy);
    setSaving(false);
    alert("Philosophy saved!");
  }

  if (loading) return <div>Loading CMS...</div>;

  return (
    <div className="space-y-12 pb-20">
      <div>
        <h1 className="text-3xl font-serif mb-2">Content Management</h1>
        <p className="text-gray-400">Update the website content dynamically.</p>
      </div>

      {/* Header Section */}
      <section className="bg-white/[0.02] border border-white/5 rounded-2xl p-8">
        <h2 className="text-xl font-serif mb-6">Header Content</h2>
        <form onSubmit={handleSaveHeader} className="space-y-4 max-w-xl">
          <div>
            <label className="block text-xs uppercase tracking-widest text-gray-400 mb-2">Logo Text</label>
            <input 
              type="text" 
              value={header.logo_text}
              onChange={e => setHeader({...header, logo_text: e.target.value})}
              className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-[#d4a853]"
            />
          </div>
          <button type="submit" disabled={saving} className="bg-[#d4a853] text-black px-6 py-2 rounded-lg font-medium hover:bg-white transition">Save Header</button>
        </form>
      </section>

      {/* Homepage Section */}
      <section className="bg-white/[0.02] border border-white/5 rounded-2xl p-8">
        <h2 className="text-xl font-serif mb-6">Homepage Hero</h2>
        <form onSubmit={handleSaveHomepage} className="space-y-4 max-w-xl">
          <div>
            <label className="block text-xs uppercase tracking-widest text-gray-400 mb-2">Hero Title</label>
            <input 
              type="text" 
              value={homepage.hero_title}
              onChange={e => setHomepage({...homepage, hero_title: e.target.value})}
              className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-[#d4a853]"
            />
          </div>
          <div>
            <label className="block text-xs uppercase tracking-widest text-gray-400 mb-2">Hero Subtitle</label>
            <input 
              type="text" 
              value={homepage.hero_subtitle}
              onChange={e => setHomepage({...homepage, hero_subtitle: e.target.value})}
              className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-[#d4a853]"
            />
          </div>
          <div>
            <label className="block text-xs uppercase tracking-widest text-gray-400 mb-2">Call to Action (CTA)</label>
            <input 
              type="text" 
              value={homepage.hero_cta}
              onChange={e => setHomepage({...homepage, hero_cta: e.target.value})}
              className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-[#d4a853]"
            />
          </div>
          <button type="submit" disabled={saving} className="bg-[#d4a853] text-black px-6 py-2 rounded-lg font-medium hover:bg-white transition">Save Homepage</button>
        </form>
      </section>

      {/* Philosophy Section */}
      <section className="bg-white/[0.02] border border-white/5 rounded-2xl p-8">
