"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@clerk/nextjs";
import { adminGetProducts, adminCreateProduct, adminUpdateProduct } from "@/features/dashboard/api";

export default function ProductsPage() {
  const { getToken } = useAuth();
  const [products, setProducts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  // Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: "", slug: "", description: "", price: 0, stock: 0, category_id: "watches"
  });

  useEffect(() => {
    loadProducts();
  }, [getToken]);

  async function loadProducts() {
    const token = await getToken();
    if (!token) return;
    try {
      const res = await adminGetProducts(token);
      setProducts(res as any);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  }

  async function handleSave(e: React.FormEvent) {
    e.preventDefault();
    const token = await getToken();
    if (!token) return;
    try {
      if (editingId) {
        await adminUpdateProduct(token, editingId, formData);
      } else {
        await adminCreateProduct(token, formData);
      }
      setEditingId(null);
      setFormData({ name: "", slug: "", description: "", price: 0, stock: 0, category_id: "watches" });
      loadProducts();
    } catch (e) {
      alert("Failed to save product");
    }
  }

  function handleEdit(product: any) {
    setEditingId(product.id);
    setFormData({
      name: product.name,
      slug: product.slug,
      description: product.description,
      price: product.price,
      stock: product.stock,
      category_id: product.category_id,
    });
  }

  if (loading) return <div>Loading products...</div>;

  return (
    <div className="space-y-12 pb-20">
      <div>
        <h1 className="text-3xl font-serif mb-2">Product Management</h1>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white/[0.02] border border-white/5 rounded-2xl overflow-hidden">
          <table className="w-full text-left text-sm text-gray-400">
            <thead className="text-xs uppercase tracking-widest bg-white/[0.02] border-b border-white/5 text-gray-500">
              <tr>
                <th className="px-6 py-4">Name</th>
                <th className="px-6 py-4">Price</th>
                <th className="px-6 py-4">Stock</th>
                <th className="px-6 py-4 text-right">Action</th>
              </tr>
            </thead>
            <tbody>
              {products.map((product) => (
                <tr key={product.id} className="border-b border-white/5 hover:bg-white/[0.01]">
                  <td className="px-6 py-4 text-white">{product.name}</td>
                  <td className="px-6 py-4">${product.price}</td>
                  <td className="px-6 py-4">{product.stock}</td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => handleEdit(product)} className="text-[#d4a853] hover:text-white transition">Edit</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="bg-white/[0.02] border border-white/5 rounded-2xl p-6 h-fit">
          <h2 className="text-lg font-serif mb-4">{editingId ? 'Edit Product' : 'Add New Product'}</h2>
          <form onSubmit={handleSave} className="space-y-4">
            <div>
              <label className="block text-xs uppercase tracking-widest text-gray-400 mb-2">Name</label>
              <input required type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-black border border-white/10 rounded px-3 py-2 text-white" />
            </div>
            <div>
              <label className="block text-xs uppercase tracking-widest text-gray-400 mb-2">Slug</label>
              <input required type="text" value={formData.slug} onChange={e => setFormData({...formData, slug: e.target.value})} className="w-full bg-black border border-white/10 rounded px-3 py-2 text-white" />
            </div>
            <div>
              <label className="block text-xs uppercase tracking-widest text-gray-400 mb-2">Category ID</label>
              <input required type="text" value={formData.category_id} onChange={e => setFormData({...formData, category_id: e.target.value})} className="w-full bg-black border border-white/10 rounded px-3 py-2 text-white" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs uppercase tracking-widest text-gray-400 mb-2">Price</label>
                <input required type="number" value={formData.price} onChange={e => setFormData({...formData, price: Number(e.target.value)})} className="w-full bg-black border border-white/10 rounded px-3 py-2 text-white" />
              </div>
              <div>
                <label className="block text-xs uppercase tracking-widest text-gray-400 mb-2">Stock</label>
                <input required type="number" value={formData.stock} onChange={e => setFormData({...formData, stock: Number(e.target.value)})} className="w-full bg-black border border-white/10 rounded px-3 py-2 text-white" />
              </div>
            </div>
            <button type="submit" className="w-full bg-[#d4a853] text-black py-2 rounded font-medium hover:bg-white transition">
              {editingId ? 'Update Product' : 'Create Product'}
            </button>
            {editingId && (
              <button type="button" onClick={() => { setEditingId(null); setFormData({ name: "", slug: "", description: "", price: 0, stock: 0, category_id: "watches" }); }} className="w-full bg-transparent border border-white/20 text-white py-2 rounded font-medium hover:bg-white/10 transition mt-2">
                Cancel
              </button>
            )}
          </form>
        </div>
      </div>
    </div>
  );
}

